    "h_statements": [
      {
        "code": "H302+H312",
        "text": "삼키거나 피부와 접촉하면 유해함.",
        "line": "p1:L31"
      },
      {
        "code": "H314",
        "text": "피부에 심한 화상과 눈에 손상을 일으킴.",
        "line": "p1:L32"
      },
      {
        "code": "H317",
        "text": "알레르기성 피부 반응을 일으킬 수 있음.",
        "line": "p1:L33"
      },
      {
        "code": "H318",
        "text": "눈에 심한 손상을 일으킴.",
        "line": "p1:L34"
      },
      {
        "code": "H361",
        "text": "태아 또는 생식능력에 손상을 일으킬 것으로 의심됨.",
        "line": "p1:L35"
      },
      {
        "code": "H373",
        "text": "장기간 또는 반복노출 되면 장기에 손상을 일으킬 수 있음.",
        "line": "p1:L36"
      },
      {
        "code": "H411",
        "text": "장기적인 영향에 의해 수생생물에게 유독함.",
        "line": "p1:L37"
      }
    ],
    "p_statements": [
      {
        "code": "P201",
        "type": "예방",
        "text": "사용 전 취급 설명서를 확보하시오.",
        "line": "p1:L40"
      },
      {
        "code": "P202",
        "type": "예방",
        "text": "모든 안전 예방조치 문구를 읽고 이해하기 전에는 취급하지 마시오.",
        "line": "p1:L41"
      },
      {
        "code": "P260",
        "type": "예방",
        "text": "미스트/증기를 흡입하지 마시오.",
        "line": "p1:L42"
      },
      {
        "code": "P260",
        "type": "예방",
        "text": "분진 또는 미스트를 흡입하지 마시오.",
        "line": "p1:L43"
      },
      {
        "code": "P264",
        "type": "예방",
        "text": "취급 후에는 취급 부위를 철저히 씻으시오.",
        "line": "p1:L44"
      },
      {
        "code": "P270",
        "type": "예방",
        "text": "이 제품을 사용할 때에는 먹거나, 마시거나 흡연하지 마시오.",
        "line": "p1:L45"
      },
      {
        "code": "P272",
        "type": "예방",
        "text": "작업장 밖으로 오염된 의복을 반출하지 마시오.",
        "line": "p1:L46"
      },
      {
        "code": "P273",
        "type": "예방",
        "text": "환경으로 배출하지 마시오.",
        "line": "p2:L1"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "보호장갑/보호의/보안경/안면보호구를(을) 착용하시오.",
        "line": "p2:L2"
      },
      {
        "code": "P330",
        "type": "대응",
        "text": "입을 씻어내시오.",
        "line": "p2:L4"
      },
      {
        "code": "P301+P330+P331",
        "type": "대응",
        "text": "삼켰다면 입을 씻어내시오. 토하게 하려 하지 마시오.",
        "line": "p2:L5"
      },
      {
        "code": "P303+P361+P353",
        "type": "대응",
        "text": "피부(또는 머리카락)에 묻으면 오염된 모든 의복을 벗으시오. 피부를 물로 씻거나 샤워하시오.",
        "line": "p2:L6"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입한 경우: 환자를 신선한 공기가 있는 곳으로 옮기고 호흡하기 편하게 할 것.",
        "line": "p2:L7"
      },
      {
        "code": "P310",
        "type": "대응",
        "text": "즉시 독성 센터/의사에 연락할 것.",
        "line": "p2:L8"
      },
      {
        "code": "P305+P351+P338",
        "type": "대응",
        "text": "눈에 묻으면: 몇 분간 물로 조심해서 씻으시오. 가능하면 콘택트렌즈를 제거하시오. 계속 씻으시오.",
        "line": "p2:L9"
      },
      {
        "code": "P333+P313",
        "type": "대응",
        "text": "피부자극성 또는 홍반이 나타나면 의학적인 조치·조언을 구하시오.",
        "line": "p2:L10"
      },
      {
        "code": "P362+P364",
        "type": "대응",
        "text": "오염된 의복은 벗고 다시 사용 전 세척하시오.",
        "line": "p2:L11"
      },
      {
        "code": "P391",
        "type": "대응",
        "text": "누출물을 모으시오.",
        "line": "p2:L12"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "잠금장치가 있는 저장장소에 저장하시오.",
        "line": "p2:L14"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "폐기물관련 법령에따라내용물/용기를폐기하시오.",
        "line": "p2:L16"
      }
    ],
